import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const createSession = (content: string): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
});

const rejectingProvider = (reason: unknown): AIProvider => ({
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator non-Error coercion', () => {
  it('coerces a thrown string to an Error for onError', async () => {
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        seenError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingProvider('boom'), promptBuilder, undefined, {hooks});

    // We expect it to still reject to the caller with the original string
    const result = await orchestrator.processMessage(createSession('hi')).catch(e => e);

    expect(result).toBe('boom');
    expect(seenError).toBeInstanceOf(Error);
    expect(seenError?.message).toBe('boom');
    // Using any because 'cause' is standard in Node 16.9.0+ but TS might need target/lib update
    expect((seenError as any).cause).toBe('boom');
  });
});

